import re
import logging
from abc import abstractmethod, ABCMeta
from six import add_metaclass
from taf.ue import ue


@add_metaclass(ABCMeta)
class PowerUeDevice(object):
    """
    PowerUeDevice API abstract base class. Parent class for implementation.
    """

    def __init__(self, ue_config, **kwargs):
        super(PowerUeDevice, self).__init__()
        self.logger = logging.getLogger("power_ue")
        self.ue_config = ue_config
        self.ue_alias = None

        self.taf_ue = ue()

        # Should be updated in each Device.
        self.support_check_source = [
            "aasyslog",
            "iperf",
        ]
        self.throughput_check_source = "iperf"

    @abstractmethod
    def prepare(self, ue_alias, ue_index=0, capabilities=0, **kwargs):
        """
        Prepare UE for L3 call, override it.
        """
        self.ue_alias = ue_alias
        pass

    def _teardown(self):
        pass

    @abstractmethod
    def teardown(self, **kwargs):
        """
        Teardown UE after test finished, override it.
        """
        pass

    @abstractmethod
    def attach(self, **kwargs):
        """
        Attach UE for L3 call, override it.
        """
        pass

    @abstractmethod
    def verify_attach(self, **kwargs):
        """
        Verify attach result when plugin verify itself insufficiently, override it.
        """
        pass

    @abstractmethod
    def detach(self, **kwargs):
        """
        Detach UE for L3 call.
        """
        pass

    @abstractmethod
    def reboot(self, **kwargs):
        """
        Reboot UE, override it.
        """
        pass

    @abstractmethod
    def start_traffic(self, dt_name, direction, **kwargs):
        """
        Start data transfer for L3 call, override it.
        """
        pass

    @abstractmethod
    def stop_traffic(self, dt_name, **kwargs):
        """
        Stop data transfer for L3 call, override it.
        """
        pass

    @abstractmethod
    def check_unidirectional_throughput(
        self,
        dt_name,
        direction,
        theoretical_throughput,
        average_tolerance="0.95",
        **kwargs
    ):
        """Check unidirectional throughput, override it"""
        pass

    @abstractmethod
    def check_bidirectional_throughput(
        self, dt_name, ul_theoretical_throughput, dl_theoretical_throughput, **kwargs
    ):
        """Check bidirectional throughput, override it"""
        pass

    @staticmethod
    def _get_tolerance_decimal(tolerance):
        tolerance = str(tolerance)
        tolerance_num = re.search(r"\d+\.?\d*", tolerance).group()
        tolerance = (
            float(tolerance) if "%" not in tolerance else float(tolerance_num) / 100
        )
        return tolerance

    @staticmethod
    def _format_throughput_unit_to_mbps(throughput):
        throughput = str(throughput) + "Mbits/sec"
        return throughput

    @staticmethod
    def _calcullate_throughput_mbps_value(throughput):
        throughput_num = re.search(r"\d+\.?\d*", str(throughput)).group()
        if "g" in throughput.lower():
            throughput = float(throughput_num) * 1000
        elif "m" in throughput.lower():
            throughput = float(throughput_num)
        elif "k" in throughput.lower():
            throughput = float(throughput_num) / 1000
        elif "bits/sec" in throughput.lower():
            throughput = float(throughput_num) / (1000 * 1000)
        else:
            throughput = float(throughput_num)
        return throughput
